{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {
      "name": "sel", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? null : datum.k", "force": true}]
    },
    {
      "name": "_kf", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? kibanaRemoveFilter({'match_phrase': {'certificate.issuer_organization': datum.k}}) : kibanaAddFilter({'match_phrase': {'certificate.issuer_organization': datum.k}})", "force": true}]
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {
          "by_issuer": {"terms": {"field": "certificate.issuer_organization", "size": 10, "order": {"_count": "desc"}}}
        }}},
      "format": {"property": "aggregations.by_issuer.buckets"},
      "transform": [
        {"type": "formula", "as": "k", "expr": "datum.key"},
        {"type": "formula", "as": "n", "expr": "datum.doc_count"},
        {"type": "collect", "sort": {"field": "n", "order": "descending"}},
        {"type": "window", "ops": ["rank"], "as": ["rnk"]},
        {"type": "formula", "as": "y",  "expr": "(datum.rnk - 1) * 52 + 52"},
        {"type": "formula", "as": "clr", "expr": "datum.rnk === 1 ? '#448aff' : datum.rnk === 2 ? '#4db6ac' : datum.rnk <= 5 ? '#546e7a' : '#37474f'"}
      ]
    },
    {
      "name": "mx",
      "source": "raw",
      "transform": [{"type": "aggregate", "ops": ["max"], "fields": ["n"], "as": ["v"]}]
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 18},
        "text": {"value": "TOP ISSUING CAs"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 10}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 34},
        "text": {"value": "CERTIFICATE AUTHORITY  —  who issued your certificates  ·  click to filter"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 42},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect", "name": "bg",
      "from": {"data": "raw"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"signal": "width"}, "height": {"value": 46},
        "fill": {"signal": "datum.k===sel ? '#1c1c2e' : '#161616'"},
        "cursor": {"value": "pointer"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "raw"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"value": 3}, "height": {"value": 46},
        "fill": {"field": "clr"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "raw"},
      "encode": {"update": {
        "x": {"value": 30}, "y": {"signal": "datum.y + 17"},
        "text": {"signal": "format(datum.rnk, 'd') + '.'"},
        "fill": {"value": "#444444"}, "fontSize": {"value": 10},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "raw"},
      "encode": {"update": {
        "x": {"value": 36}, "y": {"signal": "datum.y + 17"},
        "text": {"field": "k"}, "limit": {"signal": "width * 0.62"},
        "fill": {"signal": "datum.k===sel ? datum.clr : '#dddddd'"},
        "fontSize": {"value": 12}, "fontWeight": {"value": "bold"}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "raw"},
      "encode": {"update": {
        "x": {"value": 36}, "y": {"signal": "datum.y + 24"},
        "width": {"signal": "length(data('mx'))>0 && data('mx')[0].v > 0 ? (datum.n / data('mx')[0].v) * (width * 0.62) : 0"},
        "height": {"value": 5}, "cornerRadius": {"value": 2},
        "fill": {"signal": "datum.k===sel ? datum.clr : datum.clr + '66'"}
      }}
    },
    {
      "type": "rule",
      "from": {"data": "raw"},
      "encode": {"update": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"signal": "datum.y + 45"},
        "stroke": {"value": "#1e1e1e"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "raw"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 20"},
        "text": {"signal": "datum.n >= 1000 ? format(datum.n,'.3~s') : format(datum.n,',')"},
        "fill": {"signal": "datum.k===sel ? datum.clr : '#888888'"},
        "fontSize": {"value": 14}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {
      "name": "sel", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? null : datum.k", "force": true}]
    },
    {
      "name": "_kf", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? kibanaRemoveFilter({'match_phrase': {'certificate.subject_public_key_info.algorithm': datum.k}}) : kibanaAddFilter({'match_phrase': {'certificate.subject_public_key_info.algorithm': datum.k}})", "force": true}]
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {
          "by_algo": {"terms": {"field": "certificate.subject_public_key_info.algorithm", "size": 10}},
          "total":   {"value_count": {"field": "id"}}
        }}},
      "format": {"property": "aggregations.by_algo.buckets"},
      "transform": [
        {"type": "formula", "as": "k",   "expr": "datum.key"},
        {"type": "formula", "as": "n",   "expr": "datum.doc_count"}
      ]
    },
    {
      "name": "tot",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {"v": {"value_count": {"field": "id"}}}}},
      "format": {"property": "aggregations.v"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {
      "name": "palette",
      "values": [
        {"k": "RSA",         "clr": "#ffa726", "bg": "#ffa72618", "lbl": "RSA",         "desc": "Rivest–Shamir–Adleman — quantum-vulnerable via Shor's algorithm"},
        {"k": "ECDSA",       "clr": "#448aff", "bg": "#448aff18", "lbl": "ECDSA",       "desc": "Elliptic curve — quantum-vulnerable, efficient on classical hardware"},
        {"k": "DSA",         "clr": "#ef5350", "bg": "#ef535018", "lbl": "DSA",         "desc": "Digital Signature Algorithm — deprecated, should not be in new certs"},
        {"k": "unknown_der", "clr": "#78909c", "bg": "#78909c18", "lbl": "Unknown DER", "desc": "DER-encoded cert with unrecognized key OID"},
        {"k": "unknown_pem", "clr": "#78909c", "bg": "#78909c18", "lbl": "Unknown PEM", "desc": "PEM-encoded cert with unrecognized key OID"},
        {"k": "ML-DSA",      "clr": "#00c853", "bg": "#00c85318", "lbl": "ML-DSA",      "desc": "Lattice-based PQC signature — CNSA 2.0 quantum-resistant"},
        {"k": "SLH-DSA",     "clr": "#00c853", "bg": "#00c85318", "lbl": "SLH-DSA",     "desc": "Hash-based PQC signature — CNSA 2.0 quantum-resistant"},
        {"k": "FN-DSA",      "clr": "#00c853", "bg": "#00c85318", "lbl": "FN-DSA",      "desc": "Falcon lattice signature — CNSA 2.0 quantum-resistant"}
      ]
    },
    {
      "name": "rows",
      "source": "raw",
      "transform": [
        {"type": "lookup", "from": "palette", "key": "k", "fields": ["k"],
         "values": ["clr", "bg", "lbl", "desc"], "as": ["clr", "bg", "lbl", "desc"],
         "default": "#78909c"},
        {"type": "formula", "as": "clr",  "expr": "datum.clr  || '#78909c'"},
        {"type": "formula", "as": "bg",   "expr": "datum.bg   || '#78909c18'"},
        {"type": "formula", "as": "lbl",  "expr": "datum.lbl  || datum.k"},
        {"type": "formula", "as": "desc", "expr": "datum.desc || 'Unrecognized key algorithm'"},
        {"type": "collect", "sort": {"field": "n", "order": "descending"}},
        {"type": "window", "ops": ["rank"], "as": ["rnk"]},
        {"type": "formula", "as": "y",   "expr": "(datum.rnk - 1) * 70 + 52"},
        {"type": "formula", "as": "tot", "expr": "length(data('tot'))>0 ? data('tot')[0].n : 1"},
        {"type": "formula", "as": "pct", "expr": "datum.tot > 0 ? datum.n / datum.tot : 0"},
        {"type": "formula", "as": "bw",  "expr": "width * 0.58 - 110"}
      ]
    },
    {
      "name": "mx",
      "source": "rows",
      "transform": [{"type": "aggregate", "ops": ["max"], "fields": ["n"], "as": ["v"]}]
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 18},
        "text": {"value": "KEY ALGORITHM"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 10}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 34},
        "text": {"value": "PUBLIC KEY TYPE  —  click to filter"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 42},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect", "name": "bg",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"signal": "width"}, "height": {"value": 64},
        "fill": {"signal": "datum.k===sel ? '#1c1c2e' : datum.n>0 ? '#161622' : '#161616'"},
        "cursor": {"value": "pointer"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"value": 4}, "height": {"value": 64},
        "fill": {"field": "clr"}
      }}
    },
    {
      "type": "rule",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"signal": "datum.y + 63"},
        "stroke": {"value": "#222222"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 14}, "y": {"signal": "datum.y + 22"},
        "text": {"field": "lbl"}, "limit": {"signal": "width * 0.4"},
        "fill": {"value": "#e8e8e8"}, "fontSize": {"value": 13}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 14}, "y": {"signal": "datum.y + 40"},
        "text": {"field": "desc"}, "limit": {"signal": "width * 0.56"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width * 0.58"}, "y": {"signal": "datum.y + 22"},
        "width": {"signal": "length(data('mx'))>0 && data('mx')[0].v > 0 ? (datum.n / data('mx')[0].v) * (width * 0.30) : 0"},
        "height": {"value": 10}, "cornerRadius": {"value": 2},
        "fill": {"signal": "datum.k===sel ? datum.clr : datum.clr + '88'"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 36"},
        "text": {"signal": "datum.n >= 1000 ? format(datum.n,'.3~s') : format(datum.n,',')"},
        "fill": {"signal": "datum.k===sel ? datum.clr : '#dddddd'"},
        "fontSize": {"value": 18}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 50"},
        "text": {"signal": "format(datum.pct * 100, '.1f') + '%'"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {
      "name": "sel", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? null : datum.k", "force": true}]
    },
    {
      "name": "_kf", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? kibanaRemoveFilter({'match_phrase': {'certificate.subject_public_key_info.bit_size': datum.sz}}) : kibanaAddFilter({'match_phrase': {'certificate.subject_public_key_info.bit_size': datum.sz}})", "force": true}]
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {
          "by_size": {"terms": {"field": "certificate.subject_public_key_info.bit_size", "size": 15, "order": {"_count": "desc"}}},
          "total":   {"value_count": {"field": "id"}}
        }}},
      "format": {"property": "aggregations.by_size.buckets"},
      "transform": [
        {"type": "formula", "as": "sz",  "expr": "datum.key"},
        {"type": "formula", "as": "k",   "expr": "toString(datum.key) + '-bit'"},
        {"type": "formula", "as": "n",   "expr": "datum.doc_count"},
        {"type": "formula", "as": "clr", "expr": "datum.key <= 1024 ? '#ef5350' : datum.key <= 2048 ? '#ffa726' : datum.key <= 3072 ? '#448aff' : '#00c853'"},
        {"type": "formula", "as": "bg",  "expr": "datum.key <= 1024 ? '#ef535018' : datum.key <= 2048 ? '#ffa72618' : datum.key <= 3072 ? '#448aff18' : '#00c85318'"},
        {"type": "formula", "as": "tier","expr": "datum.key <= 512 ? 'CRITICAL' : datum.key <= 1024 ? 'WEAK' : datum.key <= 2048 ? 'CLASSICAL' : datum.key <= 3072 ? 'STRONG' : 'CNSA 2.0'"},
        {"type": "formula", "as": "desc","expr": "datum.key <= 512 ? 'Trivially breakable — remove immediately' : datum.key <= 1024 ? 'Below NIST minimum — must be replaced' : datum.key === 2048 ? 'RSA-2048 / ECDSA-P256 — classical standard, quantum-vulnerable' : datum.key === 3072 ? 'RSA-3072 — transitional strength, quantum-vulnerable' : datum.key === 4096 ? 'RSA-4096 — strong classical, quantum-vulnerable' : datum.key === 256 ? 'ECDSA-P256 — modern elliptic curve' : datum.key === 384 ? 'ECDSA-P384 — strong elliptic curve (CNSA 1.0)' : 'Key size ' + datum.key"},
        {"type": "collect", "sort": {"field": "n", "order": "descending"}},
        {"type": "window", "ops": ["rank"], "as": ["rnk"]},
        {"type": "formula", "as": "y",   "expr": "(datum.rnk - 1) * 70 + 52"}
      ]
    },
    {
      "name": "tot",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {"v": {"value_count": {"field": "id"}}}}},
      "format": {"property": "aggregations.v"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {
      "name": "mx",
      "source": "raw",
      "transform": [{"type": "aggregate", "ops": ["max"], "fields": ["n"], "as": ["v"]}]
    },
    {
      "name": "rows",
      "source": "raw",
      "transform": [
        {"type": "formula", "as": "tot", "expr": "length(data('tot'))>0 ? data('tot')[0].n : 1"},
        {"type": "formula", "as": "pct", "expr": "datum.tot > 0 ? datum.n / datum.tot : 0"}
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 18},
        "text": {"value": "KEY SIZE DISTRIBUTION"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 10}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 34},
        "text": {"value": "BIT STRENGTH  —  click to filter  ·  CNSA 2.0 requires RSA ≥3072 or ECDSA P-384"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 42},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect", "name": "bg",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"signal": "width"}, "height": {"value": 64},
        "fill": {"signal": "datum.k===sel ? '#1c1c2e' : '#161616'"},
        "cursor": {"value": "pointer"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"value": 4}, "height": {"value": 64},
        "fill": {"field": "clr"}
      }}
    },
    {
      "type": "rule",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"signal": "datum.y + 63"},
        "stroke": {"value": "#222222"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 14}, "y": {"signal": "datum.y + 22"},
        "text": {"field": "k"},
        "fill": {"value": "#e8e8e8"}, "fontSize": {"value": 13}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 14}, "y": {"signal": "datum.y + 40"},
        "text": {"field": "desc"}, "limit": {"signal": "width * 0.55"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width * 0.58"}, "y": {"signal": "datum.y + 7"},
        "width": {"value": 64}, "height": {"value": 16}, "cornerRadius": {"value": 2},
        "fill": {"field": "bg"},
        "stroke": {"field": "clr"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width * 0.58 + 32"}, "y": {"signal": "datum.y + 19"},
        "text": {"field": "tier"},
        "fill": {"field": "clr"},
        "fontSize": {"value": 8}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "center"}, "letterSpacing": {"value": 0.8}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width * 0.58"}, "y": {"signal": "datum.y + 27"},
        "width": {"signal": "length(data('mx'))>0 && data('mx')[0].v > 0 ? (datum.n / data('mx')[0].v) * 64 : 0"},
        "height": {"value": 12}, "cornerRadius": {"value": 2},
        "fill": {"signal": "datum.clr + '55'"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 36"},
        "text": {"signal": "datum.n >= 1000 ? format(datum.n,'.3~s') : format(datum.n,',')"},
        "fill": {"signal": "datum.k===sel ? datum.clr : '#dddddd'"},
        "fontSize": {"value": 18}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 50"},
        "text": {"signal": "format(datum.pct * 100, '.1f') + '%'"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
